const safeErr = (e) => {
  if (e == null) return 'unknown error';
  if (typeof e === 'string') return e;
  if (e.message || e.description) return String(e.message || e.description);
  try { return JSON.stringify(e).slice(0, 120); } catch { return 'unknown error'; }
};

// Check every active VPN server: Marzban panel if configured, else stats agent.
// Code sandbox has no fetch: use require('http'/'https') (NODE_FUNCTION_ALLOW_BUILTIN).
const http = require('http');
const https = require('https');

function request(method, url, { headers = {}, body = null, timeout = 8000 } = {}) {
  return new Promise((resolve, reject) => {
    const m = url.match(/^(https?):\/\/([^\/:]+)(?::(\d+))?(\/.*)?$/);
    if (!m) return reject(new Error('bad url: ' + url));
    const lib = m[1] === 'https' ? https : http;
    const req = lib.request({
      method, hostname: m[2], port: m[3] ? Number(m[3]) : (m[1] === 'https' ? 443 : 80),
      path: m[4] || '/', headers, timeout,
    }, (res) => {
      let data = '';
      res.on('data', (c) => data += c);
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });
    req.on('timeout', () => { req.destroy(new Error('timeout after ' + timeout + 'ms')); });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

const resp = $('Fetch VPN Servers').first().json;
const list = Array.isArray(resp.body) ? resp.body : null;

if (!list) {
  return [{ json: { servers: [], fetchError: safeErr(resp.error || 'vpn_servers fetch returned no array') } }];
}

// null/undefined is a MISSING measurement, not zero. Stats agent v2 reports
// null uplink/downlink when the counter family it sums emitted nothing, and a
// rendered "0 B" would be a lie about a number we never got.
const fmtBytes = (b) => {
  if (b == null) return 'n/a';
  if (!b) return '0 B';
  const u = ['B', 'KB', 'MB', 'GB', 'TB'];
  const i = Math.min(u.length - 1, Math.floor(Math.log(Math.abs(b)) / Math.log(1024)));
  return (b / Math.pow(1024, i)).toFixed(1) + ' ' + u[i];
};

const fmtAge = (s) => {
  if (s == null) return '?';
  if (s < 3600) return Math.round(s / 60) + 'm';
  if (s < 86400) return (Math.round(s / 360) / 10) + 'h';
  return (Math.round(s / 8640) / 10) + 'd';
};

// --- exit reachability (stats agent v2) -----------------------------------
// The agent probes chatgpt.com through the node's own egress every ~15 min in a
// background thread and serves the CACHED verdict; /stats never touches the
// network. Read the result as exit REPUTATION, not as health. Measured on all
// seven Azure nodes 2026-09-08: every one gets 403 from chatgpt.com while
// cloudflare.com and google.com both return 200. Those nodes carry VPN traffic
// perfectly well, so a `blocked` verdict raises NO warning here -- it is a
// standing condition, not an incident, and alerting on it would have paged
// seven times over on the first run after the v2 rollout for something that had
// been quietly true for months. Format Message prints it in the daily summary
// and alerts only on a CHANGE (ok <-> blocked), tracked in workflow static data.
//
// What DOES deserve a warning is the probe being broken. A cached verdict is
// supposed to be minutes old; one that has not been refreshed in hours, or that
// has never completed on an agent that has been up for hours, means we are
// measuring nothing. "unknown" must never read as "fine" -- v1 of the agent
// returned flagged:false on any exception, which is exactly that bug.
//
// Rollout note: nodes run a mix of agent v1 and v2. `agent_version` is the only
// way to tell them apart. A v1 payload has no `reachability` object at all;
// that is absence of data, neither healthy nor a problem, and is reported as
// n/a rather than folded into either bucket.
function readReach(st) {
  const agentVer = Number(st.agent_version) || 1;
  const r = (st.reachability && typeof st.reachability === 'object') ? st.reachability : null;
  if (!r) {
    return agentVer >= 2
      ? { state: 'unknown', code: null, ageS: null, stale: false, staleReason: '', label: 'openai unknown (no reachability data)' }
      : { state: 'na', code: null, ageS: null, stale: false, staleReason: '', label: 'openai n/a (agent v' + agentVer + ')' };
  }
  const code = (r.chatgpt_status == null) ? null : Number(r.chatgpt_status);
  // Trust the explicit tri-state; fall back to the compat fields only if some
  // build ships the object without a status. `flagged` is true only for blocked
  // in v2, so it can be trusted here -- but never as evidence of health.
  let state;
  if (r.status === 'ok' || r.status === 'blocked' || r.status === 'unknown') {
    state = r.status;
  } else if (r.flagged === true || code === 403) {
    state = 'blocked';
  } else if (code !== null && code >= 200 && code < 400) {
    state = 'ok';
  } else {
    state = 'unknown';
  }
  const ageS = (r.age_s == null) ? null : Number(r.age_s);
  const interval = Number(r.interval_s) || 900;
  // 8 probe intervals, floored at 4h. A 15-min probe may miss ~16 attempts
  // before we call it broken, so ordinary jitter, a restart or one flaky probe
  // never trips this; a dead probe thread always does.
  const staleAfter = Math.max(4 * 3600, interval * 8);
  const uptimeS = Number(st.uptime_s) || 0;
  const never = ageS === null;   // no probe has ever come back with a status code
  const stale = never ? (uptimeS > staleAfter) : (ageS > staleAfter);
  // A stale verdict is not a verdict. The agent keeps serving the last `ok` it
  // saw even if the probe thread has since died, so age has to override status.
  if (never || stale) state = 'unknown';

  const staleReason = !stale ? ''
    : (never ? 'no probe has completed in ' + fmtAge(uptimeS) + ' of agent uptime'
             : 'last answer ' + fmtAge(ageS) + ' ago');
  let label;
  if (state === 'ok' || state === 'blocked') {
    label = 'openai ' + state + (code === null ? '' : ' (' + code + ')') + (ageS === null ? '' : ', ' + fmtAge(ageS) + ' ago');
  } else if (stale) {
    label = 'openai unknown (' + staleReason + ')';
  } else if (never) {
    label = 'openai unknown (no probe completed yet)';
  } else {
    label = 'openai unknown' + (r.error ? ' (' + String(r.error).slice(0, 40) + ')' : (code === null ? '' : ' (HTTP ' + code + ')'));
  }
  return { state, code, ageS, stale, staleReason, label };
}

const out = [];
for (const srv of list) {
  const base = { name: srv.name, country: srv.country_code, city: srv.city, ip: srv.ip_address };
  try {
    if (srv.marzban_api_url) {
      const h = { 'Content-Type': 'application/x-www-form-urlencoded' };
      if (srv.marzban_api_key) h['X-Marzban-Key'] = srv.marzban_api_key;
      const tr = await request('POST', srv.marzban_api_url + '/admin/token', {
        headers: h,
        body: 'username=' + encodeURIComponent(srv.marzban_admin_user || '') +
              '&password=' + encodeURIComponent(srv.marzban_admin_pass || ''),
      });
      if (tr.status < 200 || tr.status >= 300) { out.push({ ...base, kind: 'marzban', ok: false, detail: 'auth HTTP ' + tr.status }); continue; }
      const token = JSON.parse(tr.body).access_token;
      const sh = { Authorization: 'Bearer ' + token };
      if (srv.marzban_api_key) sh['X-Marzban-Key'] = srv.marzban_api_key;
      const sr = await request('GET', srv.marzban_api_url + '/system', { headers: sh });
      if (sr.status < 200 || sr.status >= 300) { out.push({ ...base, kind: 'marzban', ok: false, detail: 'system HTTP ' + sr.status }); continue; }
      const sys = JSON.parse(sr.body);
      const memPct = sys.mem_total ? Math.round(100 * sys.mem_used / sys.mem_total) : null;
      // Every Doppler customer shares ONE Marzban account (default_user), so
      // total_user is 1 forever and can never approach max_users. No cap alert
      // here -- it would either never fire or fire on a number that means
      // nothing. Field names drift between panel builds, hence the fallbacks.
      const panelTotal = sys.total_user != null ? sys.total_user : (sys.total_users || 0);
      const panelActive = sys.online_users != null ? sys.online_users : (sys.users_active || 0);
      const memWarn = memPct !== null && memPct >= 90;
      // Marzban has no egress probe: reachability is simply not measured here.
      out.push({ ...base, kind: 'marzban', ok: true, warn: memWarn, warnReason: memWarn ? ('mem ' + memPct + '%') : '',
        reach: { state: 'na', code: null, ageS: null, stale: false, staleReason: '', label: '' },
        detail: panelActive + '/' + panelTotal + ' panel users (shared account), ↓' +
                fmtBytes(sys.incoming_bandwidth) + ' ↑' + fmtBytes(sys.outgoing_bandwidth) +
                (memPct === null ? '' : ', mem ' + memPct + '%') });
    } else if (srv.stats_agent_url) {
      const ar = await request('GET', srv.stats_agent_url, {
        headers: { Authorization: 'Bearer ' + (srv.stats_agent_token || '') },
      });
      if (ar.status < 200 || ar.status >= 300) { out.push({ ...base, kind: 'agent', ok: false, detail: 'agent HTTP ' + ar.status }); continue; }
      const st = JSON.parse(ar.body);
      const agentVer = Number(st.agent_version) || 1;
      const conns = (st.xray && st.xray.connections && st.xray.connections.total) || 0;
      const peers = (st.xray && st.xray.connections && st.xray.connections.distinct_peers);
      const xrayUp = !!(st.xray && st.xray.active);
      const cap = Number(srv.max_users) || 0;
      const reach = readReach(st);
      // `conns` counts SOCKETS, `max_users` counts PEOPLE. Comparing them paged
      // on nothing: measured on Hong Kong 2026-09-08, 2,197 sockets came from
      // just 33 distinct IPs, so a 150-user cap "filled" at ~2 real devices.
      // Capacity is now judged on distinct peers, which is at least the same
      // kind of quantity, and only when the agent actually reports them.
      const capNear = cap > 0 && peers != null && peers >= Math.floor(cap * 0.9);
      // Socket pressure is its own signal with its own ceiling. Heuristic, not
      // a measured limit: nf_conntrack does not track these flows (HK read
      // 200/7168 while holding 2,197 xray sockets), so there is no kernel
      // number to divide by. Set well above the observed baseline.
      const SOCKET_PRESSURE = 8000;
      const socketPressure = conns >= SOCKET_PRESSURE;
      const warns = [];
      // Deliberately NOT warning on reach.state === 'blocked'. See readReach.
      if (reach.stale) warns.push('reachability probe broken: ' + reach.staleReason);
      if (capNear) warns.push('near cap ' + peers + '/' + cap + ' devices');
      if (socketPressure) warns.push('socket pressure ' + conns + ' open');
      const reachTxt = reach.label ? ', ' + reach.label : '';
      const peersTxt = peers == null ? '' : ' from ' + peers + ' IPs' + (cap ? '/' + cap : '');
      // v2 sums exactly one counter family and names it; uplink/downlink are
      // null (not 0) when that family emitted nothing, and fmtBytes renders
      // null as n/a. Directions are xray's, from the node's point of view:
      // uplink = bytes received FROM clients, downlink = bytes sent TO them.
      const traf = (st.xray && st.xray.traffic && typeof st.xray.traffic === 'object') ? st.xray.traffic : null;
      const trafTxt = (traf && (traf.uplink != null || traf.downlink != null))
        ? ', xray in ' + fmtBytes(traf.uplink) + ' out ' + fmtBytes(traf.downlink) +
          (traf.counter_family ? ' (' + traf.counter_family + ')' : '')
        : '';
      out.push({ ...base, kind: 'agent', agentVersion: agentVer, ok: xrayUp, warn: warns.length > 0, warnReason: warns.join('; '),
        reach,
        detail: (xrayUp ? '' : 'XRAY DOWN, ') + conns + ' sockets' + peersTxt + ', load ' +
                (st.cpu ? st.cpu.load1 : '?') + ', mem ' + (st.mem ? st.mem.used_pct : '?') + '%' + trafTxt + reachTxt });
    } else {
      out.push({ ...base, kind: 'none', ok: false, detail: 'no monitoring endpoint configured' });
    }
  } catch (e) {
    out.push({ ...base, kind: srv.marzban_api_url ? 'marzban' : 'agent', ok: false, detail: safeErr(e).slice(0, 80) });
  }
}
return [{ json: { servers: out, fetchError: null } }];

const safeErr = (e) => {
  if (e == null) return 'unknown error';
  if (typeof e === 'string') return e;
  if (e.message || e.description) return String(e.message || e.description);
  try { return JSON.stringify(e).slice(0, 120); } catch { return 'unknown error'; }
};

// Build the Telegram message. Same data feeds daily summary and alerts.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function get(name) { try { return $(name).first().json; } catch { return null; } }
function isHttpOk(d) { if (!d || d.error) return false; return d.statusCode >= 200 && d.statusCode < 400; }
function errDetail(d) {
  if (!d) return 'no data';
  if (d.error) return safeErr(d.error).slice(0, 80);
  return 'HTTP ' + d.statusCode;
}

const flagMap = { PL: '\u{1F1F5}\u{1F1F1}', SE: '\u{1F1F8}\u{1F1EA}', US: '\u{1F1FA}\u{1F1F8}',
  HK: '\u{1F1ED}\u{1F1F0}', CA: '\u{1F1E8}\u{1F1E6}', DE: '\u{1F1E9}\u{1F1EA}', IL: '\u{1F1EE}\u{1F1F1}',
  RU: '\u{1F1F7}\u{1F1FA}', NL: '\u{1F1F3}\u{1F1F1}', GB: '\u{1F1EC}\u{1F1E7}', SG: '\u{1F1F8}\u{1F1EC}' };

const website = get('Check Website');
const blogApi = get('Check Blog API');
const n8nNode = get('Check n8n');
const simnetiq = get('Check Simnetiq');
const serverData = get('Check VPN Servers') || {};
const servers = serverData.servers || [];
const fetchError = serverData.fetchError || null;

// BE-05: SNI rotation coverage. Every active node must expose all six Reality
// inbounds (8443-8448) and keep >= 2 entries tagged regions:["*"]. Below that,
// an out-of-region user (Iran, Turkey, China) runs out of SNIs to rotate to and
// the tunnel silently stops recovering from a block — "connects, nothing loads".
const sniRaw = get('Fetch SNI Health');
const sniRows = (sniRaw && Array.isArray(sniRaw.body)) ? sniRaw.body : null;
const sniError = sniRows ? null : (sniRaw ? errDetail(sniRaw) : 'no data');
const sniByName = new Map((sniRows || []).map(r => [r.name, r]));
for (const srv of servers) {
  const h = sniByName.get(srv.name);
  if (!h) continue;
  const problems = [];
  if (Number(h.total_entries) !== 6) problems.push('SNI inbounds ' + h.total_entries + '/6');
  if (Number(h.global_entries) < 2) problems.push('global SNIs ' + h.global_entries + '/2');
  if (!problems.length) continue;
  srv.warn = true;
  srv.warnReason = srv.warnReason ? srv.warnReason + '; ' + problems.join('; ') : problems.join('; ');
}

const coldRaw = get('Check Cold Outreach');
const cold = (coldRaw && coldRaw.body) ? coldRaw.body : (coldRaw || {});
const hasCold = cold && typeof cold === 'object' && typeof cold.total_prospects !== 'undefined';

const icon = (ok) => ok ? '✅' : '❌';

const services = [
  { name: 'Website', ok: isHttpOk(website), data: website },
  { name: 'Blog API', ok: isHttpOk(blogApi), data: blogApi },
  { name: 'n8n', ok: isHttpOk(n8nNode), data: n8nNode },
  { name: 'Simnetiq', ok: isHttpOk(simnetiq), data: simnetiq },
];

const hasFailures = services.some(s => !s.ok) || servers.some(s => !s.ok) || servers.some(s => s.warn) || !!fetchError || !!sniError;

// Schedule fires at Berlin-local hours (container TZ Europe/Berlin); 9 = daily summary.
let hour;
try { hour = $now.hour; } catch { hour = new Date().getHours(); }
const isDailySummary = hour === 9;

// Alert dedupe: re-alert only when the failure set changes or 12h passed.
const sd = $getWorkflowStaticData('global');
const failing = [
  ...services.filter(s => !s.ok).map(s => s.name),
  ...servers.filter(s => !s.ok).map(s => s.name),
  ...servers.filter(s => s.ok && s.warn).map(s => s.name + ' (warn)'),
  ...(fetchError ? ['vpn_servers fetch'] : []),
  ...(sniError ? ['sni health check'] : []),
].sort();
const fp = failing.join('|');
const lastFp = sd.lastAlertFingerprint || '';
const lastAt = sd.lastAlertAt || 0;
const nowMs = Date.now();

// --- exit reachability: report always, alert only on a change --------------
// Exit reputation is not health. A node OpenAI refuses still carries its users'
// traffic (measured 2026-09-08: 403 from chatgpt.com, 200 from cloudflare and
// google, on all seven Azure nodes), so `blocked` never enters `failing` and
// never raises an alert on its own. A CHANGE is different: ok -> blocked means
// the exit just lost its reputation, blocked -> ok means it got it back, and
// both are worth one message.
//
// This uses the same static-data mechanism as the failure fingerprint above,
// but a SEPARATE key on purpose. Folding reachability into `fp` would make the
// failure fingerprint churn on something that is not a failure: the very next
// run would see the change gone, `fp` would differ again, and every real
// ongoing failure would be re-alerted (or, on the way back, produce a bogus
// "Recovered"). So the verdicts live in sd.reachVerdicts and only the diff is
// reported.
//
// Only `ok` and `blocked` are recorded. `unknown` (probe error, stale verdict,
// no probe yet) and `na` (agent v1, or a Marzban node that has no probe at all)
// are absence of a measurement, so they neither raise a change nor overwrite
// the last known verdict — otherwise one flaky probe would fire two messages,
// and a v1 -> v2 rollout would fire one per node.
//
// Static data is stored with the workflow, so re-importing this JSON can reset
// sd.reachVerdicts. That is safe by construction: with no previous verdict the
// next run re-baselines silently instead of announcing the whole fleet.
const prevReach = (sd.reachVerdicts && typeof sd.reachVerdicts === 'object') ? sd.reachVerdicts : {};
const reachChanges = [];
const reachGroups = { ok: [], blocked: [], unknown: [], na: [] };
const nextReach = {};
for (const srv of servers) {
  const state = (srv.reach && srv.reach.state) || 'na';
  if (reachGroups[state]) reachGroups[state].push(srv);
  if (state === 'ok' || state === 'blocked') {
    const prev = prevReach[srv.name];
    // No previous verdict = first time we have ever measured this node. That is
    // a baseline, not an event — this is what keeps the v2 rollout silent even
    // though all seven Azure exits are blocked.
    if (prev && prev !== state) reachChanges.push({ name: srv.name, from: prev, to: state, srv });
    nextReach[srv.name] = state;
  } else if (prevReach[srv.name]) {
    nextReach[srv.name] = prevReach[srv.name];   // hold the last known verdict
  }
}
// Rebuilt from the current fleet, so a decommissioned server drops out. Skipped
// entirely when the server list is missing, so a failed fetch cannot wipe the
// baseline and make the next run re-report every node.
if (!fetchError && servers.length) sd.reachVerdicts = nextReach;

let shouldSend = false;
let header = '';
if (isDailySummary) {
  shouldSend = true;
  header = '\u{1F4CA} <b>Daily Doppler Status</b>';
} else if (fp && (fp !== lastFp || nowMs - lastAt > 12 * 3600 * 1000)) {
  shouldSend = true;
  header = '\u{1F534} <b>ALERT: Service Issue</b>';
} else if (!fp && lastFp) {
  shouldSend = true;
  header = '✅ <b>Recovered — all services OK</b>';
}
if (!shouldSend && reachChanges.length) {
  shouldSend = true;
  header = '\u{1F310} <b>Exit reachability changed</b>';
}
if (shouldSend) { sd.lastAlertFingerprint = fp; sd.lastAlertAt = fp ? nowMs : 0; }

const reachIcon = { ok: '✅', blocked: '🚫', unknown: '❔', na: '➖' };

const ts = new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC';
const lines = [];
if (shouldSend) {
  lines.push(header);
  lines.push('');
  lines.push('<b>Services</b>');
  for (const s of services) {
    let detail = s.ok ? 'OK' : errDetail(s.data);
    if (s.name === 'Blog API' && s.ok && s.data.body && s.data.body.stats) {
      detail = s.data.body.stats.total_posts + ' posts, ' + s.data.body.stats.total_translations + ' translations';
    }
    lines.push(icon(s.ok) + ' <b>' + s.name + ':</b> ' + esc(detail));
  }
  lines.push('');
  lines.push('<b>VPN Servers (' + servers.length + ')</b>');
  if (fetchError) lines.push('❌ <b>server list:</b> ' + esc(fetchError));
  if (sniError) lines.push('❌ <b>sni health:</b> ' + esc(sniError));
  for (const srv of servers) {
    const flag = flagMap[srv.country] || '\u{1F310}';
    lines.push((srv.ok ? (srv.warn ? '⚠️' : '✅') : '❌') + ' ' + flag + ' <b>' + esc(srv.name) + (srv.city ? ' (' + esc(srv.city) + ')' : '') + ':</b> ' + esc(srv.detail || '') + ((srv.ok && srv.warn && srv.warnReason) ? ' — ' + esc(srv.warnReason) : ''));
  }
  if (reachChanges.length) {
    lines.push('');
    lines.push('<b>Exit reachability changed</b>');
    for (const c of reachChanges) {
      const flag = flagMap[c.srv.country] || '\u{1F310}';
      lines.push((reachIcon[c.to] || '') + ' ' + flag + ' <b>' + esc(c.name) + ':</b> openai ' + esc(c.from) + ' → ' + esc(c.to));
    }
    lines.push('<i>Reputation only — these nodes are still serving traffic.</i>');
  }
  if (isDailySummary && (reachGroups.ok.length || reachGroups.blocked.length || reachGroups.unknown.length)) {
    // A standing problem should stay visible somewhere a human reads on
    // purpose, instead of paging. This is that place.
    lines.push('');
    lines.push('<b>Exit reputation (chatgpt.com)</b>');
    for (const state of ['blocked', 'ok', 'unknown']) {
      const g = reachGroups[state];
      if (!g.length) continue;
      lines.push(reachIcon[state] + ' <b>' + state + ' (' + g.length + '):</b> ' + esc(g.map(s => s.name).join(', ')));
    }
    if (reachGroups.na.length) {
      lines.push(reachIcon.na + ' <b>not measured (' + reachGroups.na.length + '):</b> ' + esc(reachGroups.na.map(s => s.name).join(', ')));
    }
    lines.push('<i>Not a health signal: a blocked exit still carries VPN traffic.</i>');
  }
  if (isDailySummary && hasCold) {
    lines.push('');
    lines.push('<b>Cold Outreach (last 24h)</b>');
    lines.push('✉️ Sent: <b>' + (cold.sent_total_24h || 0) + '</b>  (S1: ' + (cold.sent_step1_24h || 0) + ' · S2: ' + (cold.sent_step2_24h || 0) + ' · S3: ' + (cold.sent_step3_24h || 0) + ')');
    lines.push('↩️ Replies: <b>' + (cold.replies_24h || 0) + '</b>  ·  ❌ Opt-outs: <b>' + (cold.opt_outs_24h || 0) + '</b>');
    lines.push('⏳ In queue: <b>' + (cold.in_queue || 0) + '</b>  (due now: ' + (cold.queued_due_now || 0) + ')');
    lines.push('\u{1F4C8} Lifetime: ' + (cold.total_prospects || 0) + ' prospects · ' + (cold.total_replied || 0) + ' replies · ' + (cold.total_opted_out || 0) + ' opt-outs');
  }
  lines.push('');
  lines.push('<i>' + ts + '</i>');
}
return [{ json: { shouldSend, message: lines.join('\n'), isDailySummary, hasFailures } }];
